// build. Preferring PATH keeps this instant for anyone already running a dev build, and the
// probe above is what stops it from picking a released binary that cannot do the job.
function resolveCLI() {
  if (process.env.OMP_BIN) {
    if (!accepts(process.env.OMP_BIN)) {
      throw new Error(`OMP_BIN is set to ${process.env.OMP_BIN}, which does not accept ${REQUIRED_FLAG}.`);
    }

    return process.env.OMP_BIN;
  }

  if (accepts('oh-my-posh')) {
    return 'oh-my-posh';
  }

  if (existsSync(BIN) && accepts(BIN)) {
    return BIN;
  }

  console.log(`No oh-my-posh accepting ${REQUIRED_FLAG} found, building one from src...`);
  execFileSync('go', ['build', '-o', BIN, '.'], { cwd: SRC_DIR, stdio: 'inherit' });

  return BIN;
}

function run(script, cli) {
  console.log(`Generating ${script}...`);

  const result = spawnSync('npm', ['run', script], {
    cwd: WEBSITE_DIR,
    stdio: 'inherit',
    shell: process.platform === 'win32',
    env: cli ? { ...process.env, OMP_BIN: cli } : process.env,
  });

