    // hand-written-data-file warning) and must not fail the build.
    console.warn(`${label}: ${stderr.trim()}`);
  }

  try {
    return await promises.readFile(outputPath, 'utf8');
  } finally {
    await promises.unlink(outputPath).catch(() => {});
  }
}

