const fs = require('fs');

const ESC = '\u001b';
const raw = fs.readFileSync('/tmp/ansi.txt', 'utf8');

// Strip OSC 8 hyperlink wrappers (ESC ] 8 ; ; <url> ST) and every SGR sequence, leaving the
// glyphs a terminal actually paints - the same thing the SVG's <text> nodes hold.
const plain = raw
  .split(new RegExp(ESC + '\\]8;;[^' + ESC + '\\u0007]*(?:\\u0007|' + ESC + '\\\\)', 'g')).join('')
  .split(new RegExp(ESC + '\\[[0-9;]*[a-zA-Z]', 'g')).join('')
  .split(new RegExp(ESC + '\\][^\\u0007' + ESC + ']*(?:\\u0007|' + ESC + '\\\\)', 'g')).join('');

const svg = require('D:/oh-my-posh/website/generated/hero.json').svg;
const svgText = [...svg.matchAll(/<text[^>]*>([^<]*)<\/text>/g)]
  .map((m) => m[1])
  .join('')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'");

const codes = (s) => [...s].map((c) => {
  const p = c.codePointAt(0);
  return p > 0x2000 ? 'U+' + p.toString(16).toUpperCase() : JSON.stringify(c);
}).join(' ');

console.log('ANSI len', [...plain].length, '| SVG len', [...svgText].length);
console.log();
console.log('ANSI:', codes(plain));
console.log();
console.log('SVG :', codes(svgText));

