package config

import (
	"bytes"
	"fmt"
	"os"
	"sort"
	"strconv"
	"testing"

	"github.com/stretchr/testify/require"
)

// generatedTemplatesPath is the file this test writes: the default template of every registered
// segment, as data rather than as code that has to construct one.
const generatedTemplatesPath = "segment_templates_generated.go"

// TestGenerateSegmentTemplates keeps segment_templates_generated.go in step with the registry,
// the same way TestSegmentCatalog keeps the website's registry.json in step with it: it rebuilds
// the file from config.Segments and fails if what is committed differs, naming the command that
// regenerates it.
//
// The file exists for the js/wasm build. A segment's default template is a method on its writer
// (segments.Git.Template() and 97 others), so reaching for it means constructing the writer,
// which means linking every segment package - the thing the browser build is trying to avoid,
// since it renders from recorded data and never runs a single segment's detection. Lifting the
// templates out as plain strings is what lets the writer go.
//
// Generated from the live registry rather than hand-maintained for the obvious reason: a segment
// whose template changed and whose entry here did not would render the old one in the studio and
// the new one in a terminal, from the same config.
func TestGenerateSegmentTemplates(t *testing.T) {
	types := make([]string, 0, len(Segments))
	templates := make(map[SegmentType]string, len(Segments))

	for segmentType, factory := range Segments {
		tmpl, panicked := callTemplateRecovered(t, segmentType, factory)
		if panicked {
			continue
		}

		types = append(types, string(segmentType))
		templates[segmentType] = tmpl
	}

	sort.Strings(types)

	var buf bytes.Buffer

	buf.WriteString("// Code generated by TestGenerateSegmentTemplates. DO NOT EDIT.\n\n")
	buf.WriteString("package config\n\n")
	buf.WriteString("// segmentTemplates is every registered segment's default template, lifted out of the\n")
	buf.WriteString("// writers that define them so a build with no segment packages can still render a config\n")
	buf.WriteString("// that names no template of its own. See TestGenerateSegmentTemplates.\n")
	buf.WriteString("var segmentTemplates = map[SegmentType]string{\n")

	for _, name := range types {
		segmentType := SegmentType(name)
		fmt.Fprintf(&buf, "\t%s: %s,\n", strconv.Quote(name), strconv.Quote(templates[segmentType]))
	}

	buf.WriteString("}\n")

	generated := buf.Bytes()

	committed, err := os.ReadFile(generatedTemplatesPath)
	if err == nil && bytes.Equal(normalizeNewlines(committed), normalizeNewlines(generated)) {
		return
	}

	require.NoError(t, os.WriteFile(generatedTemplatesPath, generated, 0o644))

	t.Fatalf("%s was out of date and has been regenerated; re-run the tests to confirm", generatedTemplatesPath)
}

func normalizeNewlines(b []byte) []byte {
	return bytes.ReplaceAll(b, []byte("\r\n"), []byte("\n"))
}

